<?php
// Presentation helpers only. Stock posting stays in the existing transaction controls.
function usability_shortcuts(){
 $tasks=[];
 if(can_action('add_inflow'))$tasks[]=['Receive Stocks','Deliveries, returns and cancelled orders','inflow','＋','receive'];
 if(can_action('manual_outflow'))$tasks[]=['Release Stocks','Orders and manual releases','outflow','−','release'];
 $tasks[]=['Check Stocks','Balances and product movements','stocks','▣','check'];
 if(can_action('upload_inventory_count'))$tasks[]=['Inventory Count','Upload or enter a final count','inventory_count','✓','count'];
 if(access_is_viewer()||access_profile()==='Auditor')$tasks[]=['View Reports','Balances and downloadable reports','reports','▥','reports'];
 return $tasks;
}
function usability_quick_tasks(){echo '<section class="card ux-quick-tasks" data-tour="tasks"><h3>What would you like to do?</h3><div class="ux-task-grid">';foreach(usability_shortcuts() as [$title,$detail,$page,$icon,$key])echo '<a class="ux-task" data-task="'.$key.'" href="?page='.$page.'"><span aria-hidden="true">'.$icon.'</span><strong>'.e($title).'</strong><small>'.e($detail).'</small></a>';echo '</div></section>';}
function usability_terms($compact=false){
 echo '<details class="ux-terms" data-tour="terms"><summary>Understanding inventory terms</summary><dl>';
 foreach(['Sellable Stock'=>'Ready and approved for sale.','Non-Sellable / Restricted'=>'Damaged, for packaging, or otherwise unavailable for sale.','Total Physical Stock'=>'Sellable plus Non-Sellable units recorded on hand.','Allocation'=>'Units assigned to a platform; allocation does not add physical stock.','Adjustment'=>'An approved correction based on your final count versus the system balance at cutoff.','Reconciliation'=>'Checking records to identify and explain differences before correcting them.'] as $term=>$text)echo '<div><dt>'.e($term).'</dt><dd>'.e($text).'</dd></div>';
 echo '</dl></details>';
}
function usability_journey($status,$effect,$history,$approval=false,$owner='Preparer'){
 $posted=in_array($status,['Applied','Posted','Confirmed','Complete','Successful'],true);$closed=in_array($status,['Cancelled','Reversed'],true);$pending=in_array($status,['Submitted','Awaiting Approval'],true);$error=in_array($status,['Error','Incomplete','Unsuccessful','Needs Correction'],true);
 $label=$posted?'Posted':($closed?$status:($pending?'Awaiting Admin Review & Approval':($error?'Needs Correction':'Validation / Review')));
 $next=$posted?'Check movement history'.($approval?' and update actual marketplaces manually':''):($closed?'Record closed':($pending?'Admin — a preparer cannot approve their own request':($approval?'Preparer submits; Admin reviews and approves':$owner.' reviews and confirms posting')));
 echo '<section class="card ux-journey" data-tour="journey"><div class="card-head"><h3>Transaction Status &amp; Stock Impact</h3><span class="ux-status '.($posted?'posted':($error?'error':($pending?'pending':''))).'">'.e($label).'</span></div><p><strong>'.($posted?'Posted: the recorded stock movement has been applied.':($closed?'This record is closed. Review history for any linked reversal.':'No stock has changed from this unposted transaction.')).'</strong></p><dl><div><dt>Stock affected</dt><dd>'.e($effect).'</dd></div><div><dt>Next action</dt><dd>'.e($next).'</dd></div></dl><a class="btn ghost sm" href="'.e($history).'">View linked history</a></section>';
}
function usability_activity_details($r){
 $action=(string)$r['action_type'];$details=trim((string)$r['details']);
 $summary=match(strtolower($action)){'platform transfer'=>'Stock moved between platform allocations. Total physical stock is unchanged.','create final inventory count'=>'Final count record created. No stock adjustment is posted at this step.','export inventory count'=>'Inventory count sheet prepared for counting.','change password'=>'The user changed their password.','backup complete'=>'System backup completed.','confirm order upload'=>'Order upload confirmed. Open the full record for posted totals and warnings.',default=>$action.' recorded.'};
 echo '<span class="ux-activity-summary">'.e($summary).'</span><details class="ux-activity-details"><summary>View full details</summary><dl><div><dt>Original action</dt><dd>'.e($action).'</dd></div><div><dt>Reference</dt><dd>'.e($r['entity_ref']).'</dd></div><div><dt>Recorded by</dt><dd>'.e($r['user_name']?:'System').'</dd></div><div><dt>Original details</dt><dd>'.nl2br(e($details)).'</dd></div></dl></details>';
}
function usability_activity(){
 $size=rs8_page_size('dashboard');$where="LOWER(a.action_type) NOT IN ('login','logout')";$base=history_sql('SELECT a.*,u.name user_name FROM activity_log a LEFT JOIN users u ON u.id=a.user_id WHERE '.$where);
 $total=(int)db()->query('SELECT COUNT(*) FROM ('.$base.') activity_rows')->fetchColumn();$offset=min(max(0,intdiv(max(0,(int)($_GET['activity_offset']??0)),$size)*$size),max(0,(int)ceil($total/$size)-1)*$size);
 echo '<section class="card ux-recent-activity" data-tour="history"><div class="card-head"><h3>Recent Activity</h3><a href="?page=activity">View all</a></div><div class="ux-table-flow"><table class="table"><thead><tr><th>Date</th><th>Action / User</th><th>Reference</th><th>Details</th></tr></thead><tbody>';
 foreach(db()->query($base.' ORDER BY a.id DESC LIMIT '.$size.' OFFSET '.$offset) as $r){echo '<tr><td>'.e($r['created_at']).'</td><td><strong>'.e($r['action_type']).'</strong><small>'.e($r['user_name']?:'System').'</small></td><td>'.e($r['entity_ref']).'</td><td>';usability_activity_details($r);echo '</td></tr>';}
 if(!$total)echo '<tr><td colspan="4">No activity recorded.</td></tr>';echo '</tbody></table></div>'.rs8_pagination($total,$offset,$size,['page'=>'dashboard','per_page'=>$size],'activity_offset').'</section>';
}
function usability_attention(){
 if(!process_ready())return;$groups=['Stock & Borrowed Items'=>[],'Upload Reviews'=>[],'Inventory Adjustments'=>[],'Packaging'=>[]];
 foreach([['Stock & Borrowed Items','Open Stock Exceptions',"SELECT COUNT(*) FROM stock_exceptions WHERE status='Open'",'stock_exceptions'],['Stock & Borrowed Items','Overdue Borrowed Items',"SELECT COUNT(*) FROM borrowed_items WHERE qty>returned_qty+converted_qty AND due_date<CURDATE()",'borrowed&borrow_status=Overdue'],['Stock & Borrowed Items','Borrow Conversions Pending Approval',"SELECT COUNT(*) FROM borrowed_events WHERE status='Pending'",'borrowed&borrow_status=Outstanding'],['Upload Reviews','Order Uploads Awaiting Review',"SELECT COUNT(*) FROM import_batches WHERE import_type='Orders' AND status='Review'",'imports&history=all&import_type=Orders&import_status=Review'],['Upload Reviews','Inflow Awaiting Review',"SELECT COUNT(*) FROM inflow_batches WHERE status IN ('To Review','Pending Review','Review')".(current_user()['role']==='Admin'?return_damage_inflow_exclusion_sql():''),'inflow&history=all&inflow_status=Awaiting Review']] as [$group,$label,$sql,$url])$groups[$group][]=[$label,(int)db()->query($sql)->fetchColumn(),$url];
 if(adjustments_ready()&&can_action('upload_inventory_count')){
  $filter=access_profile()==='Admin'?'':' AND created_by='.(int)current_user()['id'];$counts=[];
  foreach(db()->query("SELECT status,workflow_version,COUNT(*) total FROM inventory_count_batches WHERE status NOT IN ('Applied','Cancelled','Reversed')".$filter.' GROUP BY status,workflow_version') as $r){$status=$r['status'];$key=in_array($status,['Submitted','Awaiting Approval'],true)?'approval':($status==='Error'?'errors':($status==='Recount Required'?'legacy':'entry'));$counts[$key]=($counts[$key]??0)+(int)$r['total'];}
  foreach([['Counts Awaiting Submission','entry','Not yet submitted; the preparer validates and submits.'],['Counts Requiring Correction','errors','Resolve validation errors before submission.'],['Awaiting Admin Review & Approval','approval','Submitted counts are locked; stocks remain unchanged.']] as [$label,$key,$help])$groups['Inventory Adjustments'][]=[$label,$counts[$key]??0,'inventory_count&tab=review&attention='.$key,$help];
  if(!empty($counts['legacy']))$groups['Inventory Adjustments'][]=['Earlier Count Records — Recount Pending',$counts['legacy'],'inventory_count&tab=review&attention=legacy','Legacy records retain their original process and history.'];
 }
 if(packaging_ready())$groups['Packaging']=[['Pending RAW / Repackaging',packaging_attention(),'nonsellable&stock_view=packaging'],['Overdue Packaging',packaging_attention(true),'nonsellable&stock_view=packaging']];
 echo '<section class="card ux-attention" data-tour="attention"><h3>Needs Attention</h3><p class="muted small">Pending records grouped by process. Select a category to view its records.</p><div class="ux-attention-grid">';foreach($groups as $title=>$rows){if(!$rows)continue;echo '<section class="ux-attention-group"><h4>'.e($title).'</h4>';foreach($rows as $r)echo '<a class="ux-attention-row '.($r[1]>0?'has-pending':'').'" href="?page='.e($r[2]).'"><span>'.e($r[0]).(isset($r[3])?'<small>'.e($r[3]).'</small>':'').'</span><b>'.(int)$r[1].'</b><span aria-hidden="true">↗</span></a>';echo '</section>';}echo '</div></section>';
}
function usability_guide_steps($page){
 $steps=[['target'=>'[data-tour="tasks"]','title'=>'Start with your task','text'=>'Use these shortcuts for the work allowed by your access role. A guide never posts a transaction.'],['target'=>'[data-tour="terms"]','title'=>'Understand stock balances','text'=>'Sellable stock is ready for sale. Non-Sellable stock is restricted. Total Physical combines both. Allocation does not create extra units.'],['target'=>'[data-tour="attention"]','title'=>'Check what needs action','text'=>'Highlighted counts need attention. Neutral zero counts mean no pending records in that category.'],['target'=>'[data-tour="journey"]','title'=>'Review before posting','text'=>'Check products, quantities, item conditions, source platforms, and the stock impact. Validation alone does not change stock.'],['target'=>'[data-tour="history"]','title'=>'Confirm status and history','text'=>'Posted means stock has updated. Open linked history to check the original reference, user, and stock movement.']];
 if($page!=='dashboard')array_unshift($steps,['target'=>'[data-tour="page-context"]','title'=>'How this process works','text'=>match($page){'inflow'=>'Find the original order for returns or cancelled orders, review actual received quantities and item conditions, then validate and post.','outflow'=>'Use Upload, Review and Confirm. Register Orders reserves stock; Update Status matches existing orders and posts the first dispatch once. Manual Outflow handles other releases.','borrowed'=>'Record the borrower and due date, validate all item lines and source deductions, then post. Follow the linked borrow record for returns.','reports'=>'Choose a report, apply its filters, and generate it before downloading or printing. Report viewing does not change stock.',default=>'Review the page instructions and stock impact before confirming any action.'}],['target'=>'.page-head, .content h1, .content h2','title'=>'Your current workspace','text'=>'Read the page instructions first. Only actions allowed by your role are available. Use Help to replay this guide.']);
 if(can_action('upload_inventory_count'))$steps[]=['target'=>'a[href*="page=inventory_count"]','title'=>'Inventory count and approval','text'=>'Enter one final count, validate it, and submit to Admin. Submitted counts are locked. Only an Admin can approve; they cannot approve their own request.'];
 if(current_user()['role']==='Admin')$steps[]=['target'=>'a[href*="page=admin_requests"]','title'=>'Admin requests and approvals','text'=>'Review submitted requests here. Check the supporting details and stock impact before approving. Your own requests require another Admin.'];
 if(access_is_viewer())$steps=[['target'=>'.page-head','title'=>'Management overview','text'=>'Your role can read stock summaries and management reports. This guide does not enable transactions.'],['target'=>'a[href*="page=stocks"]','title'=>'Check stocks','text'=>'Review live sellable, Non-Sellable, and total physical balances.'],['target'=>'a[href*="page=reports"]','title'=>'Read and download reports','text'=>'Use the summary reports and available downloads for management review.']];return $steps;
}
function usability_shell($page){
 $u=current_user();$state=setting('guide_v58_user_'.(int)$u['id'],'');$config=['userId'=>(int)$u['id'],'role'=>role_label($u['role']),'auto'=>$state===''&&$page==='dashboard','steps'=>usability_guide_steps($page),'csrf'=>csrf_token()];
 echo '<script type="application/json" id="rs8-guide-config">'.json_encode($config,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script><dialog class="ux-guide-dialog" id="rs8GuideDialog" aria-labelledby="rs8GuideTitle"><div class="ux-guide-step"></div><h2 id="rs8GuideTitle"></h2><p class="ux-guide-text"></p><p class="ux-guide-context"></p><div class="ux-guide-buttons"><button type="button" class="btn ghost" data-guide-back>Back</button><button type="button" class="btn primary" data-guide-next>Next</button><button type="button" class="btn ghost" data-guide-skip>Skip tour</button></div><small class="ux-guide-save" role="status"></small></dialog>';
}
function usability_help_page(){echo '<div class="page-head"><div><h1>Help / Getting Started</h1><p>Short guides for your role: '.e(role_label(current_user()['role'])).'.</p></div></div><section class="card"><h3>Guided Page Tour</h3><p>Learn where to start, how stock balances work, and what validation and posting mean. The tour never submits a transaction.</p><button type="button" class="btn primary" data-guide-start>Start / Replay Tour</button><a class="btn ghost" href="?page=dashboard&tour=1">Tour the Dashboard</a></section>';usability_quick_tasks();usability_terms();}

function usability_page_context($page){
 $help=[
 'inflow'=>'Receive only items physically received. Validate products, quantities and conditions; posting adds stock. Use Inflow History to confirm the recorded batch.',
 'outflow'=>'Upload → Review → Confirm. Order registration reserves stock; first dispatch deducts it once. Use Order Monitoring for statuses and history.',
 'borrowed'=>'Issuing borrowed items releases sellable stock. Record returns or request a conversion using the same borrow record; conversion approval belongs to Admin.',
 'transfers'=>'Move allocations between platforms. Review source availability and destination quantities; total physical stock is unchanged.',
 'nonsellable'=>'Non-Sellable stock is physically held but unavailable for sale. Changing condition does not create units. Physical release or disposal decreases stock only after Admin approval.',
 'reconciliation'=>'Compare records to explain differences. Reconciliation is a checking process; only the confirmed correction action changes quantities.',
 'platform_inventory'=>'Allocated quantities are the system source for manual marketplace updates. Allocations do not add to total physical stock.',
 'reports'=>'Reports are read-only. Apply filters before downloading or printing; Stock Balances uses an As Of date.',
 'products'=>'Product Master defines the item identity. Editing a description or category does not record a stock movement.'
 ];
 if(isset($help[$page]))echo '<p class="ux-inline-guide" data-tour="page-context">'.e($help[$page]).'</p>';
}
